/**
 * TASK: Complete SeasonalOffer, which implements the provided Discountable
 * interface. Discountable is provided -- do not edit it.
 *
 * The interface gives you three things for free:
 *   default finalPrice()  base price minus the discount, rounded to 2 decimals
 *   default label()       "20% off"
 *   static  cheapest(...) the smallest finalPrice in a group
 *
 * You only have to supply the two abstract methods -- basePrice() and
 * discountPercent() -- and then USE the inherited members:
 *
 *   - the constructor must clamp the requested discount into 0..75, so
 *     new SeasonalOffer("Coat", 100, 200) reports 75 percent and $25.00;
 *   - label() must be overridden to put the offer name in front of the
 *     inherited text: "Coat -- 20% off". Reach the version you are replacing
 *     with Discountable.super.label();
 *   - the static helper bestPrice(...) must delegate to the interface's own
 *     static method Discountable.cheapest(...).
 *
 * Do NOT reimplement finalPrice; inherit it.
 */
interface Discountable {

    double basePrice();

    int discountPercent();

    default double finalPrice() {
        double reduction = basePrice() * discountPercent() / 100.0;
        return Math.round((basePrice() - reduction) * 100.0) / 100.0;
    }

    default String label() {
        return discountPercent() + "% off";
    }

    static double cheapest(Discountable... offers) {
        double best = Double.MAX_VALUE;
        for (Discountable offer : offers) {
            if (offer.finalPrice() < best) {
                best = offer.finalPrice();
            }
        }
        return best;
    }
}

public class SeasonalOffer implements Discountable {

    private final String name;
    private final double price;
    private final int percent;

    public SeasonalOffer(String name, double price, int percent) {
        this.name = name;
