public class SeasonalOfferTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        SeasonalOffer coat = new SeasonalOffer("Coat", 100.0, 20);
        SeasonalOffer boots = new SeasonalOffer("Boots", 19.99, 10);
        SeasonalOffer hat = new SeasonalOffer("Hat", 100.0, 200);
        SeasonalOffer scarf = new SeasonalOffer("Scarf", 40.0, -5);

        check("basePrice", 100.0, round2(coat::basePrice));
        check("inherited finalPrice", 80.0, round2(coat::finalPrice));
        check("finalPrice rounds to the cent", 17.99, round2(boots::finalPrice));
        check("a huge discount is clamped to 75", 75, safe(hat::discountPercent));
        check("and prices accordingly", 25.0, round2(hat::finalPrice));
        check("a negative discount is clamped to 0", 0, safe(scarf::discountPercent));
        check("so the price is untouched", 40.0, round2(scarf::finalPrice));
        check("label builds on the interface default", "Coat -- 20% off", safe(coat::label));
        check("clamped offers label with the clamped number", "Hat -- 75% off", safe(hat::label));
        check("bestPrice uses the static interface helper", 17.99,
                round2(() -> SeasonalOffer.bestPrice(coat, boots, hat, scarf)));

        Discountable asInterface = coat;
        check("through the interface type", 80.0, round2(asInterface::finalPrice));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

