interface Discountable {

    double basePrice();

    int discountPercent();

    default double finalPrice() {
        double reduction = basePrice() * discountPercent() / 100.0;
        return Math.round((basePrice() - reduction) * 100.0) / 100.0;
    }

    default String label() {
        return discountPercent() + "% off";
    }

    static double cheapest(Discountable... offers) {
        double best = Double.MAX_VALUE;
        for (Discountable offer : offers) {
            if (offer.finalPrice() < best) {
                best = offer.finalPrice();
            }
        }
        return best;
    }
}

public class SeasonalOffer implements Discountable {

    private final String name;
    private final double price;
    private final int percent;

    public SeasonalOffer(String name, double price, int percent) {
        this.name = name;
        this.price = price;
        if (percent < 0) {
            this.percent = 0;
        } else if (percent > 75) {
            this.percent = 75;
        } else {
            this.percent = percent;
        }
    }

    public String getName() {
        return name;
    }

    @Override
    public double basePrice() {
        return price;
    }

    @Override
    public int discountPercent() {
        return percent;
    }

    @Override
    public String label() {
        return name + " -- " + Discountable.super.label();
    }

    public static double bestPrice(SeasonalOffer... offers) {
        return Discountable.cheapest(offers);
    }
}
